def clean(s, n=200):
    return "".join(c if c.isprintable() else "?" for c in str(s))[:n]


def rows(app):
    h = app.height if isinstance(app.height, int) and app.height > 8 else 24
    return h - 6


def lines(sel, h):
    out = [f"  {len(APPS)} apps.  scope: partial = does a real part of the job; shell = a screen that says why it cannot yet", ""]
    top = max(0, min(sel - h // 2, len(APPS) - h))
    for i in range(top, min(len(APPS), top + h)):
        a = APPS[i]
        out.append(("> " if i == sel else "  ") + f"{a[1]:<24}{a[2]:<9}store.{a[0]}")
    a = APPS[sel]
    out += ["", "  " + a[4][:74], "  Not: " + a[5][:68] if a[5] else "  ", "  on: " + a[3][:72]]
    return out


def main():
    app = App()
    sel = 0
    for ev in app.events():
        if ev["cmd"] == "key":
            k = ev["key"]
            if k == "escape":
                app.exit(0)
                return
            if k == "up" and sel > 0:
                sel -= 1
            elif k == "down" and sel < len(APPS) - 1:
                sel += 1
        if ev["cmd"] != "pointer":
            app.screen(TITLE, lines(sel, rows(app) - 4), status="up/down choose   Esc leave")
